import React from "react";

export default function GuestGreeting() {
  return (
    <div>
      <h1>Please sign up.</h1>
      <h2>Available Flights</h2>
      <ul>
        <li>Flight 101 - Delhi → Mumbai</li>
        <li>Flight 202 - Kolkata → Bangalore</li>
        <li>Flight 303 - Chennai → Goa</li>
      </ul>
    </div>
  );
}
